public function loadTrads ($groupList = '', $lgSuff = null) {

    $lgSuff = $lgSuff ?: $this->lgSuff;

    $this->groupList = !empty($groupList) ? $groupList : $this->groupList;

    // aggiungo gruppi di default
    if (strlen($this->arOptions["groups"])) :
        $this->groupList = $this->arOptions["groups"].",".$this->groupList;
    endif;

    // Se ho selezionato sorgente file, filtro per gruppi e ritorno
    if ($this->arOptions["lang_source"] === 'file') {
        $trads = json_decode(file_get_contents($this->arOptions["lang_export_folder"]."/trads.json"), true);
        if (!$trads) {
            throw new Exception('Errore recupero traduzioni per lettura');
        }
        $groupFilter = explode(',', $this->groupList);
        $trads = array_filter($trads, function($rs) use ($groupFilter) {
            return in_array($rs['group_code'], $groupFilter);
        });
        foreach ($trads as $rs):
            $this->arTrads[$rs['code']] = $rs['text_'.$lgSuff];
        endforeach;
        $this->tradLoaded = true;
        return;
    }

    // Recupero traduzioni dal db
    $sql_gruppi = '';
    if (!empty($this->groupList)) {
        $sql_gruppi = " OR (";
        foreach (explode(",", $this->groupList) as $key => $gruppo) {
            $sql_gruppi .= " group_code = '". $gruppo."' OR";   
        }
        $sql_gruppi = rtrim($sql_gruppi, " OR");
        $sql_gruppi .= ")";
        $sql_gruppi .= " ORDER BY FIELD(group_code";
        foreach (explode(",", $this->groupList) as $key => $gruppo) {
            $sql_gruppi .= " ,'". $gruppo."'";   
        }
        $sql_gruppi .= ")";
    }

    // 'global' sempre + eventuali altri gruppi passati
    $result = $this->pdo->query("SELECT ".implode(",",array("code","text_".$lgSuff))." FROM ".$this->arOptions["table_trad"]."  WHERE group_code = 'global'".$sql_gruppi, PDO::FETCH_ASSOC);

    if ($result) :

        foreach ($result as $key => $rs): 

            $this->arTrads[$rs['code']] = $rs['text_'.$lgSuff];

        endforeach;
    endif;

    $this->tradLoaded = true;

}


/**
 * Recupera al volo e restituisce traduzioni appartenenti ad un'altro gruppo
 * (utile per recuperare velocemente testi non appartenenti ai gruppi principali della pagina)
 */
public function lazyGetTrads($groupList, $lgSuff = null) {

    $trads = array();

    // lingua custom se passata
    $lgSuff = $lgSuff ?: $this->lgSuff;

    // Se ho selezionato sorgente file, filtro per gruppi e ritorno
    if ($this->arOptions["lang_source"] === 'file') {
        $tempTrads = json_decode(file_get_contents($this->arOptions["lang_export_folder"]."/trads.json"), true);
        if (!$tempTrads) {
            throw new Exception('Errore recupero traduzioni per lettura');
        }
        $groupFilter = explode(',', $groupList);
        $tempTrads = array_filter($tempTrads, function($rs) use ($groupFilter) {
            return in_array($rs['group_code'], $groupFilter);
        });
        foreach ($tempTrads as $rs):
            $trads[$rs['code']] = $rs['text_'.$lgSuff];
        endforeach;
        return $trads;
    }

    // stringa query
    $sql_gruppi = '';
    if (!empty($groupList)) {
        $sql_gruppi = " WHERE group_code IN (";
        foreach (explode(",", $groupList) as $key => $gruppo) {
            $sql_gruppi .= "'". $gruppo."',";   
        }
        $sql_gruppi = rtrim($sql_gruppi, ",");
        $sql_gruppi .= ")";
        $sql_gruppi .= " ORDER BY FIELD(group_code";
        foreach (explode(",", $groupList) as $key => $gruppo) {
            $sql_gruppi .= " ,'". $gruppo."'";   
        }
        $sql_gruppi .= ")";
    }

    // recupero
    $result = $this->pdo->query("SELECT ".implode(",",array("code","text_".$lgSuff." AS text"))." FROM ".$this->arOptions["table_trad"]." ".$sql_gruppi, PDO::FETCH_ASSOC);

    if (!$result) {return $trads;}

    foreach ($result as $key => $rs): 
        $trads[$rs['code']] = $rs['text'];
    endforeach;

    return $trads;

}


